/// <summary>
/// extension of class SalesQuotationDP
/// </summary>
[ExtensionOf(classStr(SalesQuotationDP))]
final class AVASalesQuotationDPCls_Extension
{
    public CompanyInfo              clsCompanyInfo;
    public CompanyImage             clsCompanyLogo;
    public Bitmap                   clsCompanyLogoBitmap;
    public container                clsAllBPCompanies;
    public SysDocuBrandDetails      clsSysDocuBrandDetails;
    public Bitmap                   clsCompanyFooterBitmap;


    public SalesQuotationContract   clsSalesQuotationContract;

    public boolean                  clsHeaderNotesCreated;
    public AVAReportLineType        clsAVAReportLineType;
    public AVAReportLineType        clsAVAReportLineTypeOrig;
    public real                     clsLineNumSort;
    public int                      clsLineNumPos;
    public int                      clsLineNumPosSub;
    public int                      clsLineNumPosType;

    public FormLetterRemarks        clsFormLetterRemarks1;
    public FormLetterRemarks        clsFormLetterRemarks2;

}

Method.Source:
/// <summary>
/// AVA <c>initializeSalesQuotationHeaderTmp</c>
/// </summary>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
/// <param name = "_formLetterRemarks">FormLetterRemarks</param>
/// <param name = "_custFormletterDocument">CustFormletterDocument</param>
/// <param name = "_custFormletterParameters">CustFormletterParameters</param>
/// <returns>SalesQuotationHeaderTmp</returns>
 protected SalesQuotationHeaderTmp initializeSalesQuotationHeaderTmp(
    CustQuotationJour           _custQuotationJour,
    FormLetterRemarks           _formLetterRemarks,
    CustFormletterDocument      _custFormletterDocument,
    CustFormletterParameters    _custFormletterParameters)
{
    HcmWorker                   locHCMWorkerSalesTaker;
    DirPerson                   locHCMWorkerSalesTakerDirPerson;
    ContactPerson               locContactPerson;
    DirPerson                   locContactPersonDirPerson;
    KCS_KBVRequestTable         locKCS_KBVRequestTable;

    SalesQuotationHeaderTmp avaSalesQuotationHeaderTmp = next initializeSalesQuotationHeaderTmp(_custQuotationJour, _formLetterRemarks, _custFormletterDocument, _custFormletterParameters);

    // SSRS
    // deactivate standard
    avaSalesQuotationHeaderTmp.DocuRefMainNotes     = '';
    avaSalesQuotationHeaderTmp.FormLetterRemarks    = '';
    // SSRS

    HcmWorker avaWorkerSalesTaker = HcmWorker::find(_custQuotationJour.WorkerSalesTaker);
    AVASpecialDiscQuotationJour discQuotationJour = AVASpecialDiscQuotationJour::findQuotation(_custQuotationJour.RecId);

    avaSalesQuotationHeaderTmp.AVAFormLetterRemarks_Header1 = FormLetterRemarks::find(_custQuotationJour.LanguageId, FormTextType::AVASalesQuotation_Header1).Txt;
    avaSalesQuotationHeaderTmp.AVAFormLetterRemarks_Header2 = FormLetterRemarks::find(_custQuotationJour.LanguageId, FormTextType::AVASalesQuotation_Header2).Txt;

    avaSalesQuotationHeaderTmp.AVAQuotationWPrefix = strFmt('%1-%2', avaWorkerSalesTaker.PersonnelNumber, _custQuotationJour.KCS_QuotationId);
    avaSalesQuotationHeaderTmp.AVAFirstQuotationDate = _custQuotationJour.avaFirstQuotation().QuotationDate;
    avaSalesQuotationHeaderTmp.AVAQuotationExpiryDate = _custQuotationJour.AVAQuotationExpiryDate;

    if(     discQuotationJour.SpecialDiscountAmount1    != 0
        ||  discQuotationJour.SpecialDiscountPct1       != 0)
    {
        avaSalesQuotationHeaderTmp.AVASpecialDiscountAmount1    = discQuotationJour.SpecialDiscountAmount1;
        avaSalesQuotationHeaderTmp.AVASpecialDiscountTxt1       = strFmt(   SysLabel::labelId2String2(literalStr("@NDX:MinusCashDiscPerc"), _custQuotationJour.LanguageId), 
                                                                            discQuotationJour.SpecialDiscountPct1, 
                                                                            AVASpecialDiscount::txt(discQuotationJour.SpecialDiscountId1, 
                                                                                                    _custQuotationJour.LanguageId)                                          );
    }
    if(     discQuotationJour.SpecialDiscountAmount2    != 0
        ||  discQuotationJour.SpecialDiscountPct2       != 0)
    {
        avaSalesQuotationHeaderTmp.AVASpecialDiscountAmount2    = discQuotationJour.SpecialDiscountAmount2;
        avaSalesQuotationHeaderTmp.AVASpecialDiscountTxt2       = strFmt(   SysLabel::labelId2String2(literalStr("@NDX:MinusCashDiscPerc"), _custQuotationJour.LanguageId),
                                                                            discQuotationJour.SpecialDiscountPct2,
                                                                            AVASpecialDiscount::txt(discQuotationJour.SpecialDiscountId2,
                                                                                                    _custQuotationJour.LanguageId));
    }
    if(     discQuotationJour.SpecialDiscountAmount3    != 0
        ||  discQuotationJour.SpecialDiscountPct3       != 0)
    {
        avaSalesQuotationHeaderTmp.AVASpecialDiscountAmount3    = discQuotationJour.SpecialDiscountAmount3;
        avaSalesQuotationHeaderTmp.AVASpecialDiscountTxt3       = strFmt(   SysLabel::labelId2String2(literalStr("@NDX:MinusCashDiscPerc"), _custQuotationJour.LanguageId),
                                                                            discQuotationJour.SpecialDiscountPct3,
                                                                            AVASpecialDiscount::txt(discQuotationJour.SpecialDiscountId3,
                                                                                                    _custQuotationJour.LanguageId));
    }

    avaSalesQuotationHeaderTmp.AVADeliveryAddress = this.avaDeliveryString(_custQuotationJour);

    avaSalesQuotationHeaderTmp.KCS_KBVCommissSalesGroup = _custQuotationJour.KCS_KBVCommissSalesGroup;
    avaSalesQuotationHeaderTmp.KCS_QuotationAmount      = _custQuotationJour.KCS_QuotationAmount;
    avaSalesQuotationHeaderTmp.KCS_KBVBuildingProjectID = _custQuotationJour.KCS_KBVBuildingProjectID;
    avaSalesQuotationHeaderTmp.KCS_KBVSubject           = _custQuotationJour.KCS_KBVSubject;
    avaSalesQuotationHeaderTmp.KCS_TotalWeight          = _custQuotationJour.KCS_TotalWeight;

    avaSalesQuotationHeaderTmp.AVAQuotationMatValue     = _custQuotationJour.AVAQuotationMatValue;
    avaSalesQuotationHeaderTmp.AVAInvoiceAccount        = _custQuotationJour.InvoiceAccount;
    avaSalesQuotationHeaderTmp.AVAOrderAccount          = _custQuotationJour.OrderAccount;
    avaSalesQuotationHeaderTmp.AVAAddPlusVATInTotals    = TaxGroupHeading::find(_custQuotationJour.salesQuotationTable().TaxGroup).AVAAddPlusVATInTotals;

    if ((_custFormletterDocument.DocuOnQuotation == DocuOnFormular::Head) ||
        (_custFormletterDocument.DocuOnQuotation == DocuOnFormular::All))
    {
        avaSalesQuotationHeaderTmp = this.avaGetHeaderNotes(avaSalesQuotationHeaderTmp, _custQuotationJour, _custFormletterDocument);
    }

    avaSalesQuotationHeaderTmp.AVAInquirerRequest = _custQuotationJour.avaGetInquirerRequestInfo();

    // SSRS
    avaSalesQuotationHeaderTmp.CompanyLogo              = clsCompanyLogoBitmap;
    //avaSalesQuotationHeaderTmp.AVACompanyGroupLogo      = clsSysDocuBrandDetails.Image1;
    avaSalesQuotationHeaderTmp.AVACompanyGroupLogo      = clsSysDocuBrandDetails.avaPrimaryImage1(_custQuotationJour.LanguageId);
    avaSalesQuotationHeaderTmp.AVANotesLine1            = clsSysDocuBrandDetails.NotesLine1;
    //avaSalesQuotationHeaderTmp.AVACompanyPromotionImage = clsSysDocuBrandDetails.Image2;
    avaSalesQuotationHeaderTmp.AVACompanyPromotionImage = clsSysDocuBrandDetails.avaPrimaryImage2(_custQuotationJour.LanguageId);
    avaSalesQuotationHeaderTmp.AVANotesLine2            = clsSysDocuBrandDetails.NotesLine2;
    //avaSalesQuotationHeaderTmp.AVACompanyFooterImage    = clsSysDocuBrandDetails.Image3;
    avaSalesQuotationHeaderTmp.AVACompanyFooterImage    = clsSysDocuBrandDetails.avaPrimaryImage3(_custQuotationJour.LanguageId);
    avaSalesQuotationHeaderTmp.AVANotesLine3            = clsSysDocuBrandDetails.NotesLine3;
    avaSalesQuotationHeaderTmp.AVACompanyAddressLine    = clsSysDocuBrandDetails.AVASender;

    avaSalesQuotationHeaderTmp.AVAQuotationWPrefix                  = _custQuotationJour.KCS_QuotationId;

    avaSalesQuotationHeaderTmp.AVAWorkerSalesTaker                  = _custQuotationJour.WorkerSalesTaker;
    if(avaSalesQuotationHeaderTmp.AVAWorkerSalesTaker)
    {
        locHCMWorkerSalesTaker                                      = HcmWorker::find(avaSalesQuotationHeaderTmp.AVAWorkerSalesTaker);
        locHCMWorkerSalesTakerDirPerson                             = locHCMWorkerSalesTaker.DirPerson();

        avaSalesQuotationHeaderTmp.AVAQuotationWPrefix              = strFmt('%1-%2', avaWorkerSalesTaker.PersonnelNumber, _custQuotationJour.KCS_QuotationId);

        avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerEmail         = locHCMWorkerSalesTakerDirPerson.availablEmail();
        if(!avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerEmail)
        {
            avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerEmail     = locHCMWorkerSalesTaker.email();
        }
        avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerMobile        = locHCMWorkerSalesTakerDirPerson.availableMobile();
        //avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerName          = locHCMWorkerSalesTaker.name();
        avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerName          = locHCMWorkerSalesTakerDirPerson.avaGetNameWithTitle(_custQuotationJour.LanguageId);
        avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerPhone         = locHCMWorkerSalesTakerDirPerson.availablePhone();
        if(!avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerPhone)
        {
            avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerPhone     = locHCMWorkerSalesTaker.phone();
        }
        avaSalesQuotationHeaderTmp.AVAWorkerSalesTakerTeleFax       = locHCMWorkerSalesTakerDirPerson.AVAgetAvailableLogisticsElectronicAddressLocator(LogisticsElectronicAddressMethodType::Fax);
    }

    if(_custQuotationJour.AVAContactPersonId)
    {
        avaSalesQuotationHeaderTmp.AVAContactPersonId           = _custQuotationJour.AVAContactPersonId;
        locContactPerson                                        = ContactPerson::find(avaSalesQuotationHeaderTmp.AVAContactPersonId);
        if(locContactPerson.RecId)
        {
            locContactPersonDirPerson                           = locContactPerson.getPerson();
            avaSalesQuotationHeaderTmp.AVAContactPerson         = locContactPerson.RecId;

            avaSalesQuotationHeaderTmp.AVAContactPersonEmail    = _custQuotationJour.displayAVAContactPersonEmail();
            avaSalesQuotationHeaderTmp.AVAContactPersonMobile   = _custQuotationJour.displayAVAContactPersonMobile(); 
            // avaSalesQuotationHeaderTmp.AVAContactPersonName     = _custQuotationJour.displayAVAContactPersonName();
            avaSalesQuotationHeaderTmp.AVAContactPersonName     = ContactPerson::avaGetContactNameWithTitle(avaSalesQuotationHeaderTmp.AVAContactPersonId,
                                                                                                            _custQuotationJour.LanguageId);
            avaSalesQuotationHeaderTmp.AVAContactPersonPhone    = _custQuotationJour.displayAVAContactPersonPhone();
            avaSalesQuotationHeaderTmp.AVAContactPersonTeleFax  = _custQuotationJour.displayAVAContactPersonFax();
            if(     avaSalesQuotationHeaderTmp.AVAContactPersonTeleFax
                &&  _custQuotationJour.KCS_SendMode == KCS_SendMode::Fax)
            {
                avaSalesQuotationHeaderTmp.AVAContactPersonTeleFaxLine = '@@+FAX:' + strKeep(avaSalesQuotationHeaderTmp.AVAContactPersonTeleFax, '+0123456789') + '@@';
            }
        }
    }
    avaSalesQuotationHeaderTmp.AVAContactPersonSalutation   = _custQuotationJour.avaIntroduction();
    avaSalesQuotationHeaderTmp.AVAHeaderTxt                 = strFmt(   SysLabel::labelId2String2(literalStr("@NDX:NXAOfQuotationNoP1FromP2"), _custQuotationJour.LanguageId),
                                                                        avaSalesQuotationHeaderTmp.AVAQuotationWPrefix,
                                                                        avaSalesQuotationHeaderTmp.QuotationDate                                                    );

    if(_custQuotationJour.KCS_KBVRequestId)
    {
        //@NDX:NXARequestingCompany
        locKCS_KBVRequestTable = KCS_KBVRequestTable::find(_custQuotationJour.KCS_KBVRequestId);
        //avaSalesQuotationHeaderTmp.AVARequestingCompanyAddressing = AVAHelperClass::adress2singleLineFormat(locKCS_KBVRequestTable.displayOrganizationName(), locKCS_KBVRequestTable.displayAddress());
    }
    //_custQuotationJour.AVAContactPersonId;
    //_custQuotationJour.KCS_QuotationId
    // SysLabel::labelId2String2(literalStr("@SYS87980"),"de")
    // SSRS

    return avaSalesQuotationHeaderTmp;
}

/// <summary>
/// Inserts record field data into the temporary table.
/// </summary>
/// <param name = "_custQuotationJour">A <c>CustQuotationJour</c> record that the header are created from.</param>
/// <param name = "_custQuotationTrans">The <c>CustQuotationTrans</c> record that the line will be created from.</param>
/// <param name = "_custFormletterDocument">A customer form setup</param>
/// <returns>SalesQuotationDetailsTmp</returns>
protected SalesQuotationDetailsTmp createSalesQuotationDetailsTmp(  CustQuotationJour       _custQuotationJour,
                                                                    CustQuotationTrans      _custQuotationTrans,
                                                                    CustFormletterDocument  _custFormletterDocument )
{
    SalesQuotationDetailsTmp    locSalesQuotationTmp;
    // SSRS
    InventDim                   locInventDim;
    int                         locLineNumPosSub;

    clsLineNumPos++;
    clsLineNumPosSub            = 0;
    clsLineNumPosType           = 0;

    SalesQuotationLine          locSalesQuotationLine;

    locSalesQuotationLine = SalesQuotationLine::findInventTransId(_custQuotationTrans.InventTransId);
    // SSRS

    locSalesQuotationTmp = next createSalesQuotationDetailsTmp(_custQuotationJour, _custQuotationTrans, _custFormletterDocument);

    // SSRS
    ttsbegin;
    locSalesQuotationTmp.selectForUpdate(true);
    locSalesQuotationTmp.AVAReportSortNum       = this.avaCalculateSortNum();
    locSalesQuotationTmp.AVAReportSortNumClip   = 0.0 + clsLineNumPos;
    locSalesQuotationTmp.update();
    ttscommit;

    if(clsHeaderNotesCreated) // not the first time
    {
        if(locSalesQuotationTmp.KCS_QLInternalPosition <= 1)
        {
            locSalesQuotationTmp.AVAReportSortNum          = this.avaCalculateSortNum(false);
            locSalesQuotationTmp.AVANotes                  = '';
            this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                    AVAReportLineType::Partitioner  );
        }
    }
    else // only one time
    {
        // special discounts
        this.avaCreateSpecialDiscounts( locSalesQuotationTmp, 
                                        _custQuotationJour      );

        if (    _custFormletterDocument.DocuOnQuotation == DocuOnFormular::Head
            ||  _custFormletterDocument.DocuOnQuotation == DocuOnFormular::All  )
        {
            this.avaCreateNotes(locSalesQuotationTmp, 
                                _custQuotationJour, 
                                AVAReportLineType::HeaderNotePre, 
                                _custFormletterDocument             );
        }
        if (    _custFormletterDocument.DocuOnQuotation == DocuOnFormular::Head
            ||  _custFormletterDocument.DocuOnQuotation == DocuOnFormular::All  )
        {
            this.avaCreateNotes(locSalesQuotationTmp, 
                                _custQuotationJour, 
                                AVAReportLineType::HeaderNotePost, 
                                _custFormletterDocument             );
        }
        clsHeaderNotesCreated = true;
    }

    clsAVAReportLineType = AVAReportLineType::DetailLine;

    //Color
    locInventDim = _custQuotationTrans.inventDim();
    if(     locInventDim.RecId
        &&  locInventDim.InventColorId)
    {
        this.avaShiftSubNum();
        locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum();
        locSalesQuotationTmp.AVANotes           = strFmt("@SYS82282", "@SYS73726") + ': ' + locInventDim.InventColorId;
        this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                AVAReportLineType::DetailNotePost    );
    }

    if(locSalesQuotationLine.AVAPriceSurchargeCode && locSalesQuotationLine.AVAPriceSurchargePercentage != 0)
    {
        this.avaShiftSubNum();
        locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum();
        locSalesQuotationTmp.AVANotes           = strFmt(   "@NDX:NXAP1P2",
                                                            AVAPriceSurchargeTable::txt(locSalesQuotationLine.AVAPriceSurchargeCode, _custQuotationJour.LanguageId),
                                                            ' ');
        locSalesQuotationTmp.AVANotes           += strFmt(  "@NDX:NXAP1P2",
                                                            locSalesQuotationLine.AVAPriceSurchargePercentage,
                                                            '%');
        this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                AVAReportLineType::DetailNotePost    );
    }

    if (    _custFormletterDocument.DocuOnQuotation == DocuOnFormular::Line
        ||  _custFormletterDocument.DocuOnQuotation == DocuOnFormular::All  )
    {
        this.avaShiftSubNum();
        this.avaCreateNotes(locSalesQuotationTmp, _custQuotationTrans, AVAReportLineType::DetailNotePre, _custFormletterDocument);
    }

    if(_custQuotationTrans.KCS_CRMIsAlternativeLine == NoYes::Yes)
    {
        /*
        //Spacer
        locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum(false);
        locSalesQuotationTmp.AVANotes           = ' ';
        this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                AVAReportLineType::DetailNotePre    );
        */
        // alternative position information
        this.avaShiftSubNum();
        locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum(false);
        locSalesQuotationTmp.AVANotes           = SysLabel::labelId2String2(literalStr("@NDX:NDXAlternativeItem"), _custQuotationJour.LanguageId) + ':';
        this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                AVAReportLineType::DetailNotePre,
                                                AVAFormat::Bold                     );
    }

    if (    _custFormletterDocument.DocuOnQuotation == DocuOnFormular::Line
        ||  _custFormletterDocument.DocuOnQuotation == DocuOnFormular::All  )
    {
        locLineNumPosSub = clsLineNumPosSub;
        this.avaShiftSubNum(400);   // shifting from n.5 to n.9 for report sortnum to keep at the end of position
        this.avaCreateNotes(locSalesQuotationTmp, _custQuotationTrans, AVAReportLineType::DetailNotePost, _custFormletterDocument);
        clsLineNumPosSub = locLineNumPosSub;
    }

    // SSRS
    if(     locSalesQuotationTmp.AVAQLLVTotalAmount != 0
        ||  (       locSalesQuotationTmp.KCS_CRMIsAlternativeLine   == NoYes::Yes
                &&  locSalesQuotationTmp.KCS_Span                   != 0            )   )

    {
        locSalesQuotationTmp.clear();
        locSalesQuotationTmp = this.avaInitializeSalesQuotationDetailsTmp(  _custQuotationJour,
                                                                            _custQuotationTrans,
                                                                            _custFormletterDocument );

        // SSRS
        /*
        clsLineNumPos++;
        clsLineNumPosSub                        = 0;
        clsLineNumPosType                       = 0;
        */
        locSalesQuotationTmp.AVAReportSortNumClip = clsLineNumPos;
        //Spacer
        this.avaShiftSubNum();
        locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum(true);
        locSalesQuotationTmp.AVANotes           = ' ';
        this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                AVAReportLineType::DetailNotePre    );
        this.avaShiftSubNum();
        if (locSalesQuotationTmp.KCS_QLInternalPosition == CustQuotationTrans::AVAMaxInternalPosition(_custQuotationTrans.QuotationId, _custQuotationTrans.KCS_QLLVPosition))
        {
            locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum(true);
            locSalesQuotationTmp.AVAReportLineType  = AVAReportLineType::DetailSum;
            locSalesQuotationTmp.Name               = '→'; //'Σ'; //'->';
            locSalesQuotationTmp.AVANotes           = SysLabel::labelId2String2(literalStr("@NDX:TotalAmountPos"), _custQuotationJour.LanguageId) + '. ' + strFmt('%1', locSalesQuotationTmp.KCS_QLLVPosition);
            // SSRS
            this.insertSalesQuotationTmp(locSalesQuotationTmp);
        }
        // SSRS
        /*
        // group sum position information
        locSalesQuotationTmp.AVAReportSortNum   = this.avaCalculateSortNum(false);
        locSalesQuotationTmp.AVANotes           = SysLabel::labelId2String2(literalStr("@NDX:NXASpanGroup"), _custQuotationJour.LanguageId) + ':';
        this.avaInsertSalesQuotationDetailsTmp( locSalesQuotationTmp,
                                                AVAReportLineType::DetailNotePre,
                                                AVAFormat::Bold                     );
        */
        // SSRS
    }

    return locSalesQuotationTmp;
}

/// <summary>
/// Inserts record field data into the temporary table.
/// </summary>
/// <param name = "_custQuotationJour">A <c>CustQuotationJour</c> record that the header are created from.</param>
/// <param name = "_custQuotationTrans">The <c>CustQuotationTrans</c> record that the line will be created from.</param>
/// <param name = "_custFormLetterDocument">A customer form setup</param>
/// <returns>SalesQuotationDetailsTmp</returns>
public SalesQuotationDetailsTmp avaInitializeSalesQuotationDetailsTmp(
    CustQuotationJour       _custQuotationJour,
    CustQuotationTrans      _custQuotationTrans,
    CustFormLetterDocument  _custFormLetterDocument)
{
    SalesQuotationDetailsTmp salesQuotationDetailsTmp = this.initializeSalesQuotationDetailsTmp(_custQuotationJour, _custQuotationTrans, _custFormLetterDocument);

    salesQuotationDetailsTmp.AVAAltLineAmount           = _custQuotationTrans.avaGetQLLVAmountSum();
    salesQuotationDetailsTmp.AVAAlternativeReportLayout = NoYes::Yes;

    return salesQuotationDetailsTmp;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
/// <param name = "_custQuotationTrans">CustQuotationTrans</param>
/// <param name = "_custFormletterDocument">CustFormletterDocument</param>
/// <returns>SalesQuotationDetailsTmp</returns>
protected SalesQuotationDetailsTmp initializeSalesQuotationDetailsTmp(
    CustQuotationJour       _custQuotationJour,
    CustQuotationTrans      _custQuotationTrans,
    CustFormletterDocument  _custFormletterDocument)
{
    SalesQuotationDetailsTmp avaSalesQuotationTmp = next initializeSalesQuotationDetailsTmp(_custQuotationJour, _custQuotationTrans, _custFormletterDocument);
    SalesQuotationLine avaSalesQuotationLine = SalesQuotationLine::findInventTransId(_custQuotationTrans.InventTransId);

    avaSalesQuotationTmp.KCS_CRMIsAlternativeLine   = _custQuotationTrans.KCS_CRMIsAlternativeLine;
    avaSalesQuotationTmp.KCS_QLLVPosition           = _custQuotationTrans.KCS_QLLVPosition;
    avaSalesQuotationTmp.KCS_GAEBOZ                 = _custQuotationTrans.KCS_GAEBOZ ? _custQuotationTrans.KCS_GAEBOZ : avaSalesQuotationLine.KCS_GAEBOZ;
    avaSalesQuotationTmp.KCS_QLInternalPosition     = _custQuotationTrans.KCS_QLInternalPosition;
    avaSalesQuotationTmp.KCS_ModelNumber            = _custQuotationTrans.KCS_ModelNumber;
    avaSalesQuotationTmp.KCS_Span                   = _custQuotationTrans.KCS_Span;
    avaSalesQuotationTmp.AVAPriceUnit               = _custQuotationTrans.PriceUnit;
    avaSalesQuotationTmp.AVAPriceSurchargeCode      = _custQuotationTrans.AVAPriceSurchargeCode;
    avaSalesQuotationTmp.AVAPriceSurchargeDescription = AVAPriceSurchargeTranslation::findByAVAPriceSurchargeAndLanguage(AVAPriceSurchargeTable::find(_custQuotationTrans.AVAPriceSurchargeCode).RecId, _custQuotationJour.LanguageId).Description;
    avaSalesQuotationTmp.AVABarCode                 = _custQuotationTrans.AVABarCode;
    avaSalesQuotationTmp.AVAItemCode                = EcoResCategory::find(_custQuotationTrans.AVAIntrastatCommodity).Name;
    avaSalesQuotationTmp.AVASalesLineDisc           = InventTable::find(_custQuotationTrans.ItemId).inventTableModuleSales().LineDisc;
    avaSalesQuotationTmp.AVAPreferenceAuthorized    = InventTable::find(_custQuotationTrans.ItemId).NDX_PreferenceAuthorized;

    avaSalesQuotationTmp.Name                       = _custQuotationTrans.NDXProductName1;

    if(_custQuotationTrans.NDXProductName2)
    {
        avaSalesQuotationTmp.Name += '\n' + _custQuotationTrans.NDXProductName2;
    }

    if(_custQuotationTrans.KCS_QuotationShorttext == NoYes::No)
    {
        avaSalesQuotationTmp.Name += '\n' + _custQuotationTrans.Name;
    }

    if(_custQuotationJour.KCS_printWeights)
    {
        avaSalesQuotationTmp.KCS_GrossWeightME      = _custQuotationTrans.KCS_GrossWeightME;
        avaSalesQuotationTmp.KCS_GrossWeightTotal   = _custQuotationTrans.KCS_GrossWeightTotal;
    }

    if(     _custQuotationTrans.KCS_QLInternalPosition      != 0
        ||  _custQuotationTrans.KCS_CRMIsAlternativeLine    != 0)
    {
        avaSalesQuotationTmp.LineAmount         = 0;
        avaSalesQuotationTmp.AVAAltLineAmount   = _custQuotationTrans.Qty * _custQuotationTrans.SalesPrice / _custQuotationTrans.PriceUnit;
    }

    if(_custQuotationTrans.KCS_QLInternalPosition != 0
        && _custQuotationJour.KCS_ShowIntPosPrice == 0)
    {
        avaSalesQuotationTmp.SalesPrice = 0;
    }
    /* not needed anymore
    if ((_custFormletterDocument.DocuOnQuotation == DocuOnFormular::Line) ||
        (_custFormletterDocument.DocuOnQuotation == DocuOnFormular::All))
    {
        avaSalesQuotationTmp = this.avaGetFooterNotes(avaSalesQuotationTmp, _custQuotationTrans, _custFormletterDocument);
    }
    */
    if(CompanyInfo::find().NDXEldasFunctionality)
    {
        avaSalesQuotationTmp.AVAEldasENo = NDXEldas::find(_custQuotationTrans.ItemId).EldasENo;
    }

    if(_custQuotationTrans.avaIsLastInternalLVLine())
    {
        CustQuotationTrans avaTransLV;

        avaTransLV                                  = _custQuotationTrans.avaGetLVLine();
        avaSalesQuotationTmp.AVAQLLVTotalAmount     = avaTransLV.KCS_CRMIsAlternativeLine ? 0 : avaTransLV.KCS_QLLVAmount;
        avaSalesQuotationTmp.AVAQLLVTotalPrice      = avaTransLV.KCS_QLLVPrice;
        avaSalesQuotationTmp.AVAQLLVTotalPriceUnit  = avaTransLV.PriceUnit;
        avaSalesQuotationTmp.AVAQLLVTotalQty        = avaTransLV.Qty;
        avaSalesQuotationTmp.AVAQLLVSalesUnitTxt    = avaTransLV.salesUnitTxt();
    }

    // SSRS  
    avaSalesQuotationTmp.AVAReportLineType  = AVAReportLineType::DetailLine;
    avaSalesQuotationTmp.AVAFormat          = AVAFormat::Default;
    avaSalesQuotationTmp.AVAFormatStyle     = 'Default';
    avaSalesQuotationTmp.AVAFormatEffects   = 'Default';

    avaSalesQuotationTmp.NDXProductName1    = _custQuotationTrans.NDXProductName1;
    avaSalesQuotationTmp.NDXProductName2    = _custQuotationTrans.NDXProductName2;
    avaSalesQuotationTmp.AVAPAInfo          = _custQuotationTrans.AVAPAInfo;
    if(_custQuotationTrans.KCS_QuotationShorttext == NoYes::Yes)
    {
        avaSalesQuotationTmp.Name               = '';
    }
    else
    {
        avaSalesQuotationTmp.Name               = _custQuotationTrans.Name;
    }
    // SSRS

    return avaSalesQuotationTmp;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
/// <returns>str</returns>
public str avaDeliveryString(CustQuotationJour _custQuotationJour)
{
    str deliveryAddressLoc;

    deliveryAddressLoc = this.avaDeliveryAddress(_custQuotationJour);

    return deliveryAddressLoc;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_contactPersonId">ContactPersonId</param>
/// <returns>str</returns>
public str avaDeliveryContact(ContactPersonId _contactPersonId)
{
    ContactPerson contactPersonLoc = ContactPerson::find(_contactPersonId);
    DirPerson dirPersonLoc = DirPerson::find(contactPersonLoc.Party);
    DirPersonName dirPersonNameLoc = DirPersonName::find(dirPersonLoc.RecId);
    DirNameAffix nameAffixLoc = DirNameAffix::findRecId(DirNameAffixType::PersonalPrefix, dirPersonLoc.PersonalTitle);
    str contactPersonStr;

    if(nameAffixLoc)
    {
        contactPersonStr = nameAffixLoc.Affix + ' ';
    }
    if(dirPersonNameLoc.LastNamePrefix)
    {
        contactPersonStr += dirPersonNameLoc.LastNamePrefix + ' ';
    }

    contactPersonStr += dirPersonNameLoc.FirstName + ' ' + dirPersonNameLoc.LastName;

    return contactPersonStr;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
/// <returns>str</returns>
public str avaDeliveryAddress(CustQuotationJour _custQuotationJour)
{
    str                     deliveryAddressLoc;
    CustTable               locCustTable;
    LogisticsPostalAddress  addressLoc;
    smmBusRelTable          locsmmBusRelTable;

    #xppTexts

    if(_custQuotationJour.OrderAccount)
    {
        locCustTable        = CustTable::find(_custQuotationJour.OrderAccount);
        addressLoc          = locCustTable.postalAddress();
    }
    else if(_custQuotationJour.BusRelAccount)
    {
        locsmmBusRelTable   = smmBusRelTable::find(_custQuotationJour.BusRelAccount);
        addressLoc          = locsmmBusRelTable.postalAddress();
    }

    if(addressLoc.NDXLogisticsLocationName1)
    {
        deliveryAddressLoc = addressLoc.NDXLogisticsLocationName1 + #newLine;
    }
    if(addressLoc.NDXLogisticsLocationName2)
    {
        deliveryAddressLoc += addressLoc.NDXLogisticsLocationName2 + #newLine;
    }
    if(addressLoc.NDXLogisticsLocationName3)
    {
        deliveryAddressLoc += addressLoc.NDXLogisticsLocationName3 + #newLine;
    }

    if(_custQuotationJour.AVAContactPersonId)
    {
        deliveryAddressLoc += ContactPerson::avaGetContactNameWithTitle(_custQuotationJour.AVAContactPersonId, _custQuotationJour.LanguageId) + #newLine;
    }

    deliveryAddressLoc += DirUtility::replaceAddressTokenLanguage(addressLoc, _custQuotationJour.languageId);

    return deliveryAddressLoc;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesQuotationHeaderTmp">SalesQuotationHeaderTmp</param>
