/// <summary>
///     AVA <c>avaCreateSpecialDiscounts</c> method.
/// </summary>
/// <param name="_salesQuotationDetailsTmp">
///     <c>SalesQuotationDetailsTmp</c> as type
/// </param>
/// <param name="_custQuotationJT">
///     <c>Common</c> as type
/// </param>
/// <param name="_avaReportLineType">
///     <c>AVAReportLineType</c> as type
/// </param>
public void avaCreateSpecialDiscounts(  SalesQuotationDetailsTmp    _salesQuotationDetailsTmp,
                                        Common                      _custQuotationJT,
                                        AVAReportLineType           _avaReportLineType          = AVAReportLineType::HeaderMarkup)
{
    CustQuotationJour           locCustQuotationJour;
    CustQuotationTrans          locCustQuotationTrans;
    DiscAmount                  locAVASpecialDiscountAmount;
    DiscAmount                  locDiscAmountTotal;

    AVASpecialDiscQuotationJour locAVASpecialDiscQuotationJour;
    boolean                     locSpecialDiscount;
    boolean                     locSpecialDiscount1;
    boolean                     locSpecialDiscount2;
    boolean                     locSpecialDiscount3;

    TaxGroup                    locTaxGroup;
    TaxGroupHeading             locTaxGroupHeading;

    switch (_custQuotationJT.TableId)
    {
        case tableNum(CustQuotationJour):
            locCustQuotationJour            = _custQuotationJT;
            locDiscAmountTotal              = locCustQuotationJour.displayAVABaseAmount();

            locTaxGroup                     = locCustQuotationJour.SalesQuotationTable().TaxGroup;
            if(locTaxGroup)
            {
                locTaxGroupHeading = TaxGroupHeading::find(locTaxGroup);
            }

            locAVASpecialDiscQuotationJour  = AVASpecialDiscQuotationJour::findQuotation(locCustQuotationJour.RecId);
            if(locAVASpecialDiscQuotationJour.RecId)
            {
                clsAVAReportLineTypeOrig    = clsAVAReportLineType;
                clsAVAReportLineType        = _avaReportLineType;

                if(     locAVASpecialDiscQuotationJour.SpecialDiscountAmount1   != 0
                    ||  locAVASpecialDiscQuotationJour.SpecialDiscountPct1      != 0    )
                {
                    locSpecialDiscount1 = true;
                    locSpecialDiscount  = true;
                }
                if(     locAVASpecialDiscQuotationJour.SpecialDiscountAmount2   != 0
                    ||  locAVASpecialDiscQuotationJour.SpecialDiscountPct2      != 0    )
                {
                    locSpecialDiscount2 = true;
                    locSpecialDiscount  = true;
                }
                if(     locAVASpecialDiscQuotationJour.SpecialDiscountAmount3   != 0
                    ||  locAVASpecialDiscQuotationJour.SpecialDiscountPct3      != 0    )
                {
                    locSpecialDiscount3 = true;
                    locSpecialDiscount  = true;
                }
                locAVASpecialDiscountAmount = locCustQuotationJour.avaSpecialDiscAmount(true);

                /*
                _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                _salesQuotationDetailsTmp.AVASpecialDiscountId              = '';
                _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = 0.0;
                _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = '';
                _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = SysLabel::labelId2String2(literalStr("@NDX:NDXSpecialDiscount"), locCustQuotationJour.LanguageId) + ':';
                this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);
                */
                _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                _salesQuotationDetailsTmp.AVASpecialDiscountId              = '';
                _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locDiscAmountTotal;
                _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = locCustQuotationJour.CurrencyCode;
                if(locSpecialDiscount)
                {
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt         = SysLabel::labelId2String2(literalStr("@NDX:NXAQuotationAmountMaterial"), locCustQuotationJour.LanguageId) + ':';
                }
                else
                {
                    if(locTaxGroupHeading.AVAAddPlusVATInTotals)
                    {
                        _salesQuotationDetailsTmp.AVASpecialDiscountTxt     = SysLabel::labelId2String2(literalStr("@NDX:NXAQuotationAmountMaterialPlusVAT"), locCustQuotationJour.LanguageId) + ':';
                    }
                    else
                    {
                        _salesQuotationDetailsTmp.AVASpecialDiscountTxt      = SysLabel::labelId2String2(literalStr("@NDX:NXAQuotationAmountMaterial"), locCustQuotationJour.LanguageId) + ':';
                    }
                }
                this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);

                if(locSpecialDiscount1)
                {
                    _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                    _salesQuotationDetailsTmp.AVASpecialDiscountId              = locAVASpecialDiscQuotationJour.SpecialDiscountId1;
                    _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locAVASpecialDiscQuotationJour.SpecialDiscountAmount1;
                    //_salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locCustQuotationJour.avaSpecialDiscAmount(true, 1);
                    _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = locCustQuotationJour.CurrencyCode;
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = strFmt(SysLabel::labelId2String2(literalStr("@NDX:MinusCashDiscPerc"), locCustQuotationJour.LanguageId),  locAVASpecialDiscQuotationJour.SpecialDiscountPct1,
                                                                                                                                                                                            AVASpecialDiscount::txt(locAVASpecialDiscQuotationJour.SpecialDiscountId1,
                                                                                                                                                                                            locCustQuotationJour.LanguageId));
                    this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);
                }
                if(locSpecialDiscount2)
                {
                    _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                    _salesQuotationDetailsTmp.AVASpecialDiscountId              = locAVASpecialDiscQuotationJour.SpecialDiscountId2;
                    _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locAVASpecialDiscQuotationJour.SpecialDiscountAmount2;
                    //_salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locCustQuotationJour.avaSpecialDiscAmount(true, 2);
                    _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = locCustQuotationJour.CurrencyCode;
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = strFmt(SysLabel::labelId2String2(literalStr("@NDX:MinusCashDiscPerc"), locCustQuotationJour.LanguageId),  locAVASpecialDiscQuotationJour.SpecialDiscountPct2,
                                                                                                                                                                                            AVASpecialDiscount::txt(locAVASpecialDiscQuotationJour.SpecialDiscountId2,
                                                                                                                                                                                            locCustQuotationJour.LanguageId));
                    this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);
                }
                if(locSpecialDiscount3)
                {
                    _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                    _salesQuotationDetailsTmp.AVASpecialDiscountId              = locAVASpecialDiscQuotationJour.SpecialDiscountId3;
                    _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locAVASpecialDiscQuotationJour.SpecialDiscountAmount3;
                    //_salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locCustQuotationJour.avaSpecialDiscAmount(true, 3);
                    _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = locCustQuotationJour.CurrencyCode;
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = strFmt(SysLabel::labelId2String2(literalStr("@NDX:MinusCashDiscPerc"), locCustQuotationJour.LanguageId),  locAVASpecialDiscQuotationJour.SpecialDiscountPct3,
                                                                                                                                                                                            AVASpecialDiscount::txt(locAVASpecialDiscQuotationJour.SpecialDiscountId3,
                                                                                                                                                                                            locCustQuotationJour.LanguageId));
                    this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);
                }
                // if special discount set markup sum header in special discount block
                if(locSpecialDiscount)
                {
                    _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                    _salesQuotationDetailsTmp.AVASpecialDiscountId              = '';
                    _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locDiscAmountTotal - locAVASpecialDiscountAmount;
                    _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = locCustQuotationJour.CurrencyCode;
                    if(locTaxGroupHeading.AVAAddPlusVATInTotals)
                    {
                        _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = SysLabel::labelId2String2(literalStr("@NDX:NXATotalQuotationAmountMaterialPlusVAT"), locCustQuotationJour.LanguageId);
                    }
                    else
                    {
                        _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = SysLabel::labelId2String2(literalStr("@NDX:NXATotalQuotationAmountMaterial"), locCustQuotationJour.LanguageId);
                    }
                    this.avaInsertSalesQuotationDetailsTmp( _salesQuotationDetailsTmp,
                                                            AVAReportLineType::HeaderMarkupSum  );
                }
                // header sum after positions
                _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                _salesQuotationDetailsTmp.AVASpecialDiscountId              = '';
                _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = locDiscAmountTotal;
                _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = locCustQuotationJour.CurrencyCode;
                if(locTaxGroupHeading.AVAAddPlusVATInTotals)
                {
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = SysLabel::labelId2String2(literalStr("@NDX:NXAQuotationAmountMaterialPlusVAT"), locCustQuotationJour.LanguageId);
                }
                else
                {
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             = SysLabel::labelId2String2(literalStr("@NDX:NXAQuotationAmountMaterial"), locCustQuotationJour.LanguageId);
                }
                this.avaInsertSalesQuotationDetailsTmp( _salesQuotationDetailsTmp,
                                                        AVAReportLineType::HeaderSum  );
                // if special discount spacer
                if(locSpecialDiscount)
                {
                    _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                    _salesQuotationDetailsTmp.AVASpecialDiscountId              = '';
                    _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = 0.0;
                    _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = '';
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             =  ' ';
                    this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);
                }
                if(locCustQuotationJour.RespiteDate != dateNull())
                {
                    _salesQuotationDetailsTmp.AVAReportSortNum                  = this.avaCalculateSortNum();
                    _salesQuotationDetailsTmp.AVASpecialDiscountId              = '';
                    _salesQuotationDetailsTmp.AVASpecialDiscountAmount          = 0.0;
                    _salesQuotationDetailsTmp.AVASpecialDiscountCurrencyCode    = '';
                    _salesQuotationDetailsTmp.AVASpecialDiscountTxt             =       SysLabel::labelId2String2(literalStr("@NDX:PriceBinding"), locCustQuotationJour.LanguageId) + ': '
                                                                                    +   strFmt('%1', locCustQuotationJour.RespiteDate)
                                                                                    +   ' '
                                                                                    +   SysLabel::labelId2String2(literalStr("@NDX:WithReservation"), locCustQuotationJour.LanguageId);
                    this.avaInsertSalesQuotationDetailsTmp(_salesQuotationDetailsTmp);
                }

                clsAVAReportLineType    = clsAVAReportLineTypeOrig;
            }
            break;

        case tableNum(CustQuotationTrans):
            locCustQuotationTrans   = _custQuotationJT;
            break;

        default:
            // default statement
            break;
    }
}

/// <summary>
///     AVA <c>avaCreateNotes</c> method.
/// </summary>
/// <param name="_salesQuotationDetailsTmp">
///     <c>SalesQuotationDetailsTmp</c> as type
/// </param>
/// <param name="_custQuotationJT">
///     <c>Common</c> as type
/// </param>
/// <param name="_avaReportLineType">
///     <c>AVAReportLineType</c> as type
/// </param>
/// <param name="_custFormLetterDocument">
///     <c>CustFormletterDocument</c> as type
/// </param>
public void avaCreateNotes( SalesQuotationDetailsTmp    _salesQuotationDetailsTmp,
                            Common                      _custQuotationJT, 
                            AVAReportLineType           _avaReportLineType, 
                            CustFormletterDocument      _custFormLetterDocument     )
{
    CustQuotationJour   locCustQuotationJour;
    CustQuotationTrans  locCustQuotationTrans;
    DocuRefSearch       locDocuRefSearch;
    DocuRef             locDocuRef;
    boolean             locAfterPosition;
    int                 locLineNumPosType;
    Notes               locnotes;
    int                 partLines;
    int                 numOfLines, numOfBlankLines;
    int                 posCRLF, curPos, prevPos;
    Map                 map;
    MapEnumerator       mapEnumerator;
    //String255           lineStr, notesSubStr;
    notes           lineStr, notesSubStr;
    String10            lastPart;

    clsAVAReportLineTypeOrig    = clsAVAReportLineType;
    clsAVAReportLineType        = _avaReportLineType;

    locAfterPosition            = true;

    switch (_custQuotationJT.TableId)
    {
        case tableNum(CustQuotationJour):
            locCustQuotationJour    = _custQuotationJT;

            if(_avaReportLineType       == AVAReportLineType::HeaderNotePre)
            {
                locAfterPosition    = false;
                locDocuRefSearch    = DocuRefSearch::avaNewTypeAndRestrictAndNotePositionSortDesc(  locCustQuotationJour,
                                                                                                    _custFormletterDocument.DocuTypeQuotation,
                                                                                                    DocuRestriction::External,
                                                                                                    AVATCVNotePosition::Top);
            }
            else if(_avaReportLineType  == AVAReportLineType::HeaderNotePost)
            {
                locAfterPosition    = true;
                locDocuRefSearch    = DocuRefSearch::avaNewTypeAndRestrictAndNotePositionSortDesc(  locCustQuotationJour,
                                                                                                    _custFormletterDocument.DocuTypeQuotation,
                                                                                                    DocuRestriction::External,
                                                                                                    AVATCVNotePosition::Bottom);
            }
            break;

        case tableNum(CustQuotationTrans):
            locCustQuotationTrans   = _custQuotationJT;

            if(_avaReportLineType       == AVAReportLineType::DetailNotePre)
            {
                locAfterPosition    = false;
                locDocuRefSearch    = DocuRefSearch::avaNewTypeAndRestrictAndNotePositionSortDesc(  locCustQuotationTrans,
                                                                                                    _custFormletterDocument.DocuTypeQuotation,
                                                                                                    DocuRestriction::External,
                                                                                                    AVATCVNotePosition::Top);
            }
            else if(_avaReportLineType  == AVAReportLineType::DetailNotePost)
            {
                locAfterPosition    = true;
                locDocuRefSearch    = DocuRefSearch::avaNewTypeAndRestrictAndNotePositionSortDesc(  locCustQuotationTrans,
                                                                                                    _custFormletterDocument.DocuTypeQuotation,
                                                                                                    DocuRestriction::External,
                                                                                                    AVATCVNotePosition::Bottom);
            }
            break;

        default:
            // default statement
            break;
    }

    while (locDocuRefSearch.next())
    {

        locDocuRef                                          = locDocuRefSearch.docuRef();

        // nur Positionsnotizen teilen (wg. Seitenumbruch)
        if (_avaReportLineType == AVAReportLineType::DetailNotePost || _avaReportLineType == AVAReportLineType::DetailNotePre || _avaReportLineType == AVAReportLineType::HeaderNotePre)
        {
            partLines = AVASalesParameters::find().PartitionLines;
        }

        if (partLines > 0)
        {
            locnotes = locDocuRef.Notes;
            numOfLines = 0;
            posCRLF = 1;
            numOfBlankLines = 0;
            curPos = 0;
            map = new Map(Types::Integer, Types::Integer) ;

            while (locnotes)
            {
                if (subStr(locnotes, 1, 1) == '\n')   //CrLf
                {
                    curPos++;
                    locnotes = subStr(locnotes, 2, strLen(locnotes));
                    numOfLines++;
                    if ((numOfLines - numOfBlankLines) > partLines)
                    {
                        map.add(numOfLines, curPos);
                        numOfBlankLines = numOfLines;
                    }
                }
                else
                {
                    posCRLF = strFind(locnotes, '\n', 1, strLen(locnotes));
                    if (!posCRLF)
                    {
                        locnotes = '';
                    }
                    else
                    {
                        numOfLines++;
                        curPos += posCRLF;
                        lineStr = locnotes;
                        LineStr = subStr(lineStr, 1,posCRLF);
                        lastPart = subStr(lineStr, posCRLF - 1, 1);
                        if (lastPart != '=' && lastPart != '-' && lastPart != '*' && lastPart != '_' && strLen(strAlpha(lineStr)) == 0 && strLen(locnotes) > 0)   //Zeile aus Leerzeichen     
                        {
                            if ((numOfLines - numOfBlankLines) > partLines)
                            {
                                map.add(numOfLines, curPos);
                                numOfBlankLines = numOfLines;
                            }
                        }
                        locnotes = subStr(locnotes,posCRLF + 1, strLen(locnotes));
                    }
                }
            }

            mapEnumerator = map.getEnumerator();
            prevPos = 1;
            while (mapEnumerator.moveNext())
            {
                curPos = mapEnumerator.currentValue();
                if (subStr(locDocuRef.Notes, curPos, 1) == '\n')
                {
                    notesSubStr                  = subStr(locDocuRef.Notes, prevPos, curPos - 1 - prevpos);
                    _salesQuotationDetailsTmp.AVANotes                  = notesSubStr;
                }
                else
                {
                    notesSubStr                  = subStr(locDocuRef.Notes, prevPos, curPos - prevPos);
                    _salesQuotationDetailsTmp.AVANotes                  = notesSubStr;
                }
                _salesQuotationDetailsTmp.KCS_TCVLineNum            = locDocuRef.KCS_TCVLineNum;
                clsLineNumPosType                                   = locDocuRef.KCS_TCVLineNum;
                _salesQuotationDetailsTmp.AVAReportSortNum          = this.avaCalculateSortNum(locAfterPosition);
                if(clsLineNumPosType > locLineNumPosType)
                {
                    locLineNumPosType = clsLineNumPosType; // keep highest
                }

                this.avaInsertSalesQuotationDetailsTmp( _salesQuotationDetailsTmp,
                                                _avaReportLineType,
                                                locDocuRef.AVAFormat          );

                prevPos = curPos;
            }

            _salesQuotationDetailsTmp.AVANotes                  = subStr(locDocuRef.Notes, prevPos, strLen(locDocuRef.Notes));
            _salesQuotationDetailsTmp.KCS_TCVLineNum            = locDocuRef.KCS_TCVLineNum;
            clsLineNumPosType                                   = locDocuRef.KCS_TCVLineNum;
            _salesQuotationDetailsTmp.AVAReportSortNum          = this.avaCalculateSortNum(locAfterPosition);
            if(clsLineNumPosType > locLineNumPosType)
            {
                locLineNumPosType = clsLineNumPosType; // keep highest
            }

            this.avaInsertSalesQuotationDetailsTmp( _salesQuotationDetailsTmp,
                                                clsAVAReportLineType,
                                                locDocuRef.AVAFormat          );
        }
        else
        {
            _salesQuotationDetailsTmp.AVANotes                  = locDocuRef.Notes;
            _salesQuotationDetailsTmp.KCS_TCVLineNum            = locDocuRef.KCS_TCVLineNum;
            clsLineNumPosType                                   = locDocuRef.KCS_TCVLineNum;
            _salesQuotationDetailsTmp.AVAReportSortNum          = this.avaCalculateSortNum(locAfterPosition);
            if(clsLineNumPosType > locLineNumPosType)
            {
                locLineNumPosType = clsLineNumPosType; // keep highest
            }

            this.avaInsertSalesQuotationDetailsTmp( _salesQuotationDetailsTmp,
                                                clsAVAReportLineType,
                                                locDocuRef.AVAFormat          );
        }

    }

    clsLineNumPosType = locLineNumPosType;

    clsAVAReportLineType    = clsAVAReportLineTypeOrig;
}

/// <summary>
///     AVA <c>avaShiftSubNum</c> method.
/// </summary>
/// <param name="_lineNumPosSub">
///     <c>int</c> as type
/// </param>
public void avaShiftSubNum(int _lineNumPosSub = 0)
{
    if(_lineNumPosSub)
    {
        clsLineNumPosSub = _lineNumPosSub;
    }
    else
    {
        clsLineNumPosSub++;
    }
    clsLineNumPosType = 0;
}

/// <summary>
///     AVA <c>avaCalculateSortNum</c> method.
/// </summary>
/// <param name="_after">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>real</c> as return value
/// </returns>
public real avaCalculateSortNum(boolean _after = true)
{
    clsLineNumSort = clsLineNumPos;

    if(_after)
    {
        clsLineNumSort += 0.5;
    }
    clsLineNumSort = clsLineNumSort + (clsLineNumPosSub / 1000) + (clsLineNumPosType / 1000000);
    clsLineNumPosType++;

    return clsLineNumSort;
}

/// <summary>
///     AVA <c>avaInsertSalesQuotationDetailsTmp</c> method.
/// </summary>
/// <param name="_salesQuotationDetailsTmp">
///     <c>SalesQuotationDetailsTmp</c> as type
/// </param>
/// <param name="_avaReportLineType">
///     <c>AVAReportLineType</c> as type
/// </param>
/// <param name="_avaFormat">
///     <c>AVAFormat</c> as type
/// </param>
public void avaInsertSalesQuotationDetailsTmp(  SalesQuotationDetailsTmp    _salesQuotationDetailsTmp,
                                                AVAReportLineType           _avaReportLineType          = clsAVAReportLineType,
                                                AVAFormat                   _avaFormat                  = AVAFormat::Default)
{
    _salesQuotationDetailsTmp.AVAReportLineType         = _avaReportLineType;
    _salesQuotationDetailsTmp.AVAFormat                 = _avaFormat;        
    [   _salesQuotationDetailsTmp.AVAFormatStyle,
        _salesQuotationDetailsTmp.AVAFormatEffects  ]   = AVAHelperClass::getStyleAndEffectsFromAVAFormat(_salesQuotationDetailsTmp.AVAFormat);

    switch(_avaReportLineType)
    {
        case AVAReportLineType::Partitioner :
            _salesQuotationDetailsTmp.AVANotes  = '';
            break;

        case AVAReportLineType::Spacer:
            _salesQuotationDetailsTmp.AVANotes  = ' ';
            break;

        default:
            break;
    }

    _salesQuotationDetailsTmp.insert();

    switch(_avaReportLineType)
    {
        case AVAReportLineType::DetailNotePre :
        case AVAReportLineType::DetailNotePost :
            break;
        case AVAReportLineType::HeaderNotePre :
        case AVAReportLineType::HeaderNotePost :
        case AVAReportLineType::Spacer:
            _salesQuotationDetailsTmp.AVANotes  = '';
            _salesQuotationDetailsTmp.KCS_TCVLineNum  = 0.0;
            break;

        default:
            _salesQuotationDetailsTmp.AVANotes  = '';
            _salesQuotationDetailsTmp.KCS_TCVLineNum  = 0.0;
            break;
    }

}
